#!/usr/bin/env python3
"""Regenerate the CSX-145 Q1 non-choice ground truth from local package data."""

from __future__ import annotations

import json
import re
from datetime import date
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-145"


SOURCES = {
    "event": "metadata/event.json",
    "locked_anchor": "data/event_reports/event_reports_004_Locked_event_anchor_Super_Typhoon_Yagi_severe_wind_and_rainfall_impacts.json",
    "un_report": "data/event_reports/event_reports_001_Locked_anchor_report_NOAA_NESDIS.html",
    "noaa_report": "data/event_reports/event_reports_003_event_package.json_source_plan.locked_event_anchor.evidence_url.html",
    "gpm": "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "chirps": "data/physical_hazard/physical_hazard_008_CHIRPS_daily_event_accumulated_precipitation.json",
}


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        text = " ".join(data.split())
        if text:
            self.parts.append(text)

    @property
    def text(self) -> str:
        return " ".join(self.parts)


def load_json(rel_path: str) -> dict[str, Any]:
    return json.loads((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8"))


def load_html_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8", errors="ignore"))
    return parser.text


def find_float(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1).replace(",", ""))


def event_window() -> tuple[str, str]:
    locked_anchor = load_json(SOURCES["locked_anchor"])
    window = locked_anchor["temporal_window"]
    return window["start_date"], window["end_date"]


def inclusive_days(start: str, end: str) -> int:
    start_date = date.fromisoformat(start)
    end_date = date.fromisoformat(end)
    return (end_date - start_date).days + 1


def report_values() -> dict[str, float]:
    un_text = load_html_text(SOURCES["un_report"])
    noaa_text = load_html_text(SOURCES["noaa_report"])
    return {
        "reported_landfall_wind_kmh": find_float(r"wind speeds reaching\s+([0-9,]+)\s+kilometres", un_text),
        "reported_landfall_wind_mph": find_float(r"\(([0-9,]+)\s+miles\)\s+per hour", un_text),
        "evacuated_people_threshold": find_float(r"evacuation of over\s+([0-9,]+)\s+people", un_text),
        "deaths_threshold": find_float(r"at least\s+([0-9,]+)\s+people", un_text),
        "damaged_or_destroyed_houses_threshold": find_float(r"over\s+([0-9,]+)\s+houses damaged", un_text),
        "regional_rain_inches": find_float(r"dumping\s+([0-9.]+)\s+inches", noaa_text),
        "regional_rain_cm": find_float(r"\(([0-9.]+)\s*cm\)\s+of rain", noaa_text),
        "noaa_sustained_wind_mph": find_float(r"sustained wind speeds of around\s+([0-9.]+)\s+miles per hour", noaa_text),
    }


def build_calculations() -> dict[str, Any]:
    start, end = event_window()
    reports = report_values()
    gpm_max = float(load_json(SOURCES["gpm"])["stats"]["gpm_event_precip_mm_max"])
    chirps_max = float(load_json(SOURCES["chirps"])["stats"]["chirps_event_precip_mm_max"])

    wind_kmh_from_mph = reports["reported_landfall_wind_mph"] * 1.609344
    rain_mm_from_cm = reports["regional_rain_cm"] * 10
    rain_mm_from_inches = reports["regional_rain_inches"] * 25.4

    gridded_max_values = sorted([gpm_max, chirps_max])
    regional_to_gridded_peak_ratio = rain_mm_from_cm / gridded_max_values[1]
    wind_unit_pair_ratio = wind_kmh_from_mph / reports["reported_landfall_wind_kmh"]
    rain_unit_pair_ratio = rain_mm_from_cm / rain_mm_from_inches

    return {
        "event_window": {
            "start_date": start,
            "end_date": end,
            "inclusive_days": inclusive_days(start, end),
        },
        "report_values": {
            **reports,
            "wind_kmh_from_133_mph": round(wind_kmh_from_mph, 2),
            "rain_mm_from_25_cm": round(rain_mm_from_cm, 2),
            "rain_mm_from_10_inches": round(rain_mm_from_inches, 2),
            "noaa_sustained_wind_kmh": round(reports["noaa_sustained_wind_mph"] * 1.609344, 2),
        },
        "regional_precipitation": {
            "gpm_event_precip_mm_max": round(gpm_max, 2),
            "chirps_event_precip_mm_max": round(chirps_max, 2),
        },
        "unit_checks": {
            "wind_kmh_from_133_mph": round(wind_kmh_from_mph, 2),
            "wind_difference_kmh": round(abs(wind_kmh_from_mph - reports["reported_landfall_wind_kmh"]), 2),
            "rain_mm_from_25_cm": round(rain_mm_from_cm, 2),
            "rain_difference_mm_between_25cm_and_10in": round(abs(rain_mm_from_cm - rain_mm_from_inches), 2),
        },
        "hazard_contrasts": {
            "reported_wind_unit_pair_ratio": round(wind_unit_pair_ratio, 2),
            "rain_unit_pair_ratio": round(rain_unit_pair_ratio, 2),
            "regional_to_gridded_peak_rainfall_ratio": round(regional_to_gridded_peak_ratio, 2),
            "gridded_rain_max_ratio": round(gridded_max_values[1] / gridded_max_values[0], 2),
        },
        "impact_ratios": {
            "evacuees_per_death_report_threshold": round(
                reports["evacuated_people_threshold"] / reports["deaths_threshold"], 2
            ),
            "houses_per_death_report_threshold": round(
                reports["damaged_or_destroyed_houses_threshold"] / reports["deaths_threshold"], 2
            ),
        },
    }


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "JSON answer structure",
                "points": 4,
                "description": "Includes the answer label, 7-day window, unit checks, hazard contrasts, impact ratios, consistency tests, and a concise conclusion.",
                "partial_credit": "2-3 points if one or two required fields are missing; 1 point if the answer is prose only but contains most values.",
            },
            {
                "name": "Unit conversion checks",
                "points": 5,
                "description": "Computes 214.04 km/h, 1.04 km/h wind difference, 250.0 mm rainfall from 25 cm, 4.0 mm rain-unit difference, and unit_pairs_consistent = true.",
                "partial_credit": "3-4 points for one arithmetic or rounding error; 1-2 points for correct formulas with multiple incorrect values.",
            },
            {
                "name": "Hazard contrast calculations",
                "points": 4,
                "description": "Uses the report unit-pair ratios, regional-to-gridded peak rainfall ratio, and 1.47 gridded precipitation max ratio without relying on off-event local point weather.",
                "partial_credit": "2-3 points if one contrast is wrong; 1 point if ratios are attempted but use the wrong source family.",
            },
            {
                "name": "Impact threshold ledger",
                "points": 3,
                "description": "Computes 279.33 and 265.36 while treating the report values as thresholds, not exact final loss rates.",
                "partial_credit": "2 points for one correct ratio; 1 point for the right division setup with incorrect arithmetic.",
            },
            {
                "name": "Decision-rule application",
                "points": 2,
                "description": "Correctly marks the compact weather-layer test and single-layer diagnosis as failing the stated tests.",
                "partial_credit": "1 point if only one of the two pass/fail states is correct.",
            },
            {
                "name": "Concise computed interpretation",
                "points": 1,
                "description": "Uses a compact compound wind-rain-impact interpretation tied to the calculated ledger.",
                "partial_credit": "0.5 points if the interpretation is directionally right but not tied to the ledger.",
            },
            {
                "name": "Overstatement control",
                "points": 1,
                "description": "Avoids exact-loss overstatement, broad event narration, and extra instructions beyond the computed ledger.",
                "partial_credit": "0.5 points if the answer has minor extra prose but does not change the conclusion.",
            },
        ],
    }


def build_gt() -> dict[str, Any]:
    event = load_json(SOURCES["event"])
    values = build_calculations()
    unit_checks = values["unit_checks"]
    hazard_contrasts = values["hazard_contrasts"]
    impact_ratios = values["impact_ratios"]
    consistency_tests = {
        "unit_pairs_consistent": (
            unit_checks["wind_difference_kmh"] <= 2
            and unit_checks["rain_difference_mm_between_25cm_and_10in"] <= 5
        ),
        "compact_weather_layer_passes": (
            hazard_contrasts["regional_to_gridded_peak_rainfall_ratio"] <= 3
            and impact_ratios["evacuees_per_death_report_threshold"] < 50
            and impact_ratios["houses_per_death_report_threshold"] < 50
        ),
        "single_layer_diagnosis_passes": False,
    }
    consistency_tests["single_layer_diagnosis_passes"] = (
        consistency_tests["unit_pairs_consistent"] and consistency_tests["compact_weather_layer_passes"]
    )

    answer = "compound_wind_rain_impact_chain_not_compact_weather_layer"
    conclusion = (
        "The unit pairs are internally consistent, but the regional-to-gridded rainfall scale contrast and "
        "impact-threshold ratios reject a single compact weather-layer diagnosis."
    )
    return {
        "schema_version": "1.0",
        "task_id": "CSX-145_Q1",
        "event_id": "CSX-145",
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "formula_derivation_consistency_proof",
        "primary_gt": {
            "answer": answer,
            "event_window_days": values["event_window"]["inclusive_days"],
            "unit_checks": unit_checks,
            "hazard_contrasts": hazard_contrasts,
            "impact_ratios": impact_ratios,
            "consistency_tests": consistency_tests,
            "conclusion": conclusion,
        },
        "numeric_tolerances": {
            "ratios_abs": 0.05,
            "unit_values_abs": 0.05,
        },
        "answer_schema": {
            "required_top_level_fields": [
                "answer",
                "event_window_days",
                "unit_checks",
                "hazard_contrasts",
                "impact_ratios",
                "consistency_tests",
                "conclusion",
            ],
            "rounding": "Ratios and derived unit values should be rounded to two decimals.",
        },
        "event": {
            "event_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": "tropical_cyclone_typhoon",
            "metadata_hazard_family_raw": event["hazard_family"],
            "event_date_or_window": f"{values['event_window']['start_date']} to {values['event_window']['end_date']}",
        },
        "decision_rule": {
            "unit_pairs_consistent": "wind difference <= 2 km/h and rain-unit difference <= 5 mm",
            "compact_weather_layer_passes": "regional-to-gridded peak rainfall ratio <= 3 and both impact threshold ratios are below 50",
            "single_layer_diagnosis_passes": "unit pairs are consistent and compact_weather_layer_passes is true",
            "expected_result": "unit pairs pass; compact weather-layer and single-layer diagnosis fail",
        },
        "key_values": values,
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": list(SOURCES.values()),
            "notes": [
                "Off-event Open-Meteo and NASA POWER point-weather fills were removed from the official calculation.",
                "The ledger uses report unit checks, declared package-relative gridded precipitation summaries, and report impact thresholds.",
            ],
        },
    }


def main() -> None:
    output = TASK_DIR / "computed_gt.json"
    output.write_text(json.dumps(build_gt(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
